    /*
     * Assign a Plant
     * 
     * @param	parentId	UUID
     * @param	assignment 	Plant 
     * @return	ProductionSchedule
     */
    public ProductionSchedule assignPlant( UUID parentId, Plant assignment ) {
	    LOGGER.info("assigning Plant as " + assignment.toString() );

	    ProductionSchedule parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Plant.class, assignment.getPlantId());

	    // ------------------------------------------
		// assign the Plant to the parent entity
		// ------------------------------------------ 
	    parentEntity.setPlant( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Plant
	 * 
	 * @param	parentId		UUID
	 * @return	ProductionSchedule
	 */
	public ProductionSchedule unAssignPlant( UUID parentId ) {
		ProductionSchedule parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Plant on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Plant on the parent entithy
		// ------------------------------------------     
	    parentEntity.setPlant(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the WorkOrders
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	ProductionSchedule
     */
    public ProductionSchedule addToWorkOrders( UUID parentId, WorkOrder addTo ) {
	    LOGGER.info("handling AssignWorkOrdersToProductionScheduleEvent - " );
	    
	    ProductionSchedule parentEntity = repository.findById(parentId).get();
	    WorkOrder child = registry.project( WorkOrder.class, addTo.getWorkOrderId());
	    
	    parentEntity.getWorkOrders().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the WorkOrders
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	ProductionSchedule
     */
	public ProductionSchedule removeFromWorkOrders( UUID parentId, WorkOrder removeFrom ) {
	    LOGGER.info("handling RemoveWorkOrdersFromProductionScheduleEvent " );
	
	    ProductionSchedule parentEntity = repository.findById(parentId).get();
	    WorkOrder child = registry.project( WorkOrder.class, removeFrom.getWorkOrderId());
	    
	    parentEntity.getWorkOrders().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



